database-considerations.required-migration:

-- Remove unique constraint to allow multiple entries per period
ALTER TABLE daep_daily_points
DROP CONSTRAINT IF EXISTS daep_daily_points_tenant_id_placement_id_date_period_key;

-- Add is_base_points column to distinguish auto vs manual entries
ALTER TABLE daep_daily_points
ADD COLUMN IF NOT EXISTS is_base_points BOOLEAN DEFAULT false;

-- Add index for efficient querying
CREATE INDEX IF NOT EXISTS idx_daep_daily_points_lookup
ON daep_daily_points(tenant_id, placement_id, date);

story-context.validation-schema:

// Add to lib/validation/schemas.ts

export const PointAdjustmentSchema = z.object({
  placement_id: z.string().uuid('Invalid placement ID'),
  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Date must be YYYY-MM-DD'),
  period: z.string().min(1, 'Period is required'),
  adjustment_value: z.enum(['+10', '+5', '0', '-5', '-10', '-15']),
  student_action: z.string().optional(),
  teacher_action: z.string().optional(),
  notes: z.string().max(500).optional(),
});

export type PointAdjustmentInput = z.infer<typeof PointAdjustmentSchema>;

// Response types
export interface DailyPointsSummary {
  placement_id: string;
  base_points: number;      // Sum of base points (10 per present period)
  adjustments: number;      // Sum of adjustment values
  day_total: number;        // base_points + adjustments
  periods_present: number;  // Count of periods marked present
  expected_points: number;  // periods_present * 10
  percentage: number;       // (day_total / expected_points) * 100
}

server-action-patterns.pattern:

// Called when attendance is marked present
// Idempotent - won't duplicate if already exists
export async function createBasePoints(
  placementId: string,
  date: string,
  period: string
): Promise<void> {
  const supabase = await createServerClient();
  const tenantId = await getTenantId();
  const user = await currentUser();

  // Check if base points already exist for this period
  const { data: existing } = await supabase
    .from('daep_daily_points')
    .select('id')
    .eq('tenant_id', tenantId)
    .eq('placement_id', placementId)
    .eq('date', date)
    .eq('period', period)
    .eq('is_base_points', true)
    .single();

  if (existing) return; // Already exists, skip

  await supabase.from('daep_daily_points').insert({
    tenant_id: tenantId,
    placement_id: placementId,
    date,
    period,
    points_earned: 10,
    is_base_points: true,
    entered_by: user.id,
    approval_status: 'approved',
    public: true,
  });
}


export async function createPointAdjustment(
  input: PointAdjustmentInput
): Promise<{ success: boolean; error?: string }> {
  const validated = PointAdjustmentSchema.parse(input);
  const supabase = await createServerClient();
  const tenantId = await getTenantId();
  const user = await currentUser();

  // Convert adjustment string to number
  const adjustmentValue = parseInt(validated.adjustment_value);

  const { error } = await supabase.from('daep_daily_points').insert({
    tenant_id: tenantId,
    placement_id: validated.placement_id,
    date: validated.date,
    period: validated.period,
    points_earned: adjustmentValue,
    is_base_points: false,
    student_action: validated.student_action,
    teacher_action: validated.teacher_action,
    notes: validated.notes,
    entered_by: user.id,
    approval_status: 'approved',
    public: true,
  });

  if (error) {
    return { success: false, error: 'Failed to save adjustment. Please try again.' };
  }

  // Audit log
  await logDAEPAuditEvent(supabase, 'points.adjustment_added', user.id,
    validated.placement_id, 'Added point adjustment', tenantId, {
      date: validated.date,
      period: validated.period,
      adjustment: adjustmentValue,
      student_action: validated.student_action,
      teacher_action: validated.teacher_action,
    });

  return { success: true };
}
